import{_ as r,C as i,o as l,c as n,ak as a,E as o,j as d,a as c}from"./chunks/framework.DxrHb2fb.js";const C=JSON.parse('{"title":"CartesianChart 直角坐标图","description":"","frontmatter":{},"headers":[],"relativePath":"components/cartesian-chart.md","filePath":"components/cartesian-chart.md","lastUpdated":1790454556000}'),h={name:"components/cartesian-chart.md"};function s(p,t,u,b,m,g){const e=i("XhDemo");return l(),n("div",null,[t[0]||(t[0]=a('<h1 id="cartesianchart-直角坐标图" tabindex="-1">CartesianChart 直角坐标图 <a class="header-anchor" href="#cartesianchart-直角坐标图" aria-label="Permalink to &quot;CartesianChart 直角坐标图&quot;">​</a></h1><p>在直角坐标系里画柱与折线：一根自变量轴（类目、数值或时间），一根数值轴，任意多个系列共用这两根轴。柱状图、条形图、分组与堆叠柱、折线、面积与堆叠面积都是它的不同配置，不是不同的组件。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/cartesian-chart" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/cartesian-chart.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/cartesian-chart" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/cartesian-chart" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/cartesian-chart.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>一个柱系列：x 取类目字段，y 取数值字段，悬停或用方向键逐个查看</p>',5)),o(e,{src:"cartesian-chart/01-basic"}),t[1]||(t[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;cartesian-chart&quot;</code>：<strong><code>root</code></strong> · <code>caption</code> · <code>legend</code> · <code>legend-item</code> · <code>legend-swatch</code> · <code>legend-label</code> · <strong><code>viewport</code></strong> · <strong><code>plot</code></strong> · <code>grid</code> · <code>grid-line</code> · <code>axis</code> · <code>axis-line</code> · <code>tick</code> · <code>tick-label</code> · <code>axis-title</code> · <code>series</code> · <code>bar</code> · <code>line</code> · <code>area-fill</code> · <code>dot</code> · <code>point</code> · <code>data-label</code> · <code>total-label</code> · <code>end-label</code> · <code>leader-line</code> · <code>crosshair</code> · <code>focus-ring</code> · <code>tooltip</code> · <code>tooltip-header</code> · <code>tooltip-row</code> · <code>tooltip-swatch</code> · <code>tooltip-value</code> · <code>tooltip-name</code> · <code>empty</code> · <code>summary</code> · <code>table</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="多系列折线" tabindex="-1">多系列折线 <a class="header-anchor" href="#多系列折线" aria-label="Permalink to &quot;多系列折线&quot;">​</a></h3><p>三条折线共用坐标轴，图例点一下隐藏或恢复一个系列，其余系列颜色不变</p>',6)),o(e,{src:"cartesian-chart/02-lines"}),t[2]||(t[2]=d("h3",{id:"堆叠柱",tabindex:"-1"},[c("堆叠柱 "),d("a",{class:"header-anchor",href:"#堆叠柱","aria-label":'Permalink to "堆叠柱"'},"​")],-1)),t[3]||(t[3]=d("p",null,"同一个 stack 名的柱系列首尾相接，柱高是各部分之和，相邻两段之间留一道表面缝",-1)),o(e,{src:"cartesian-chart/03-stack"}),t[4]||(t[4]=d("h3",{id:"横向条形图",tabindex:"-1"},[c("横向条形图 "),d("a",{class:"header-anchor",href:"#横向条形图","aria-label":'Permalink to "横向条形图"'},"​")],-1)),t[5]||(t[5]=d("p",null,'orientation="horizontal" 把整张图转置：类目名竖排可以读全，数值横向延伸',-1)),o(e,{src:"cartesian-chart/04-horizontal"}),t[6]||(t[6]=d("h3",{id:"百分比堆叠面积",tabindex:"-1"},[c("百分比堆叠面积 "),d("a",{class:"header-anchor",href:"#百分比堆叠面积","aria-label":'Permalink to "百分比堆叠面积"'},"​")],-1)),t[7]||(t[7]=d("p",null,"stackOffset: 'expand' 把每个键归一到 100%，看的是构成随时间的变化而不是总量",-1)),o(e,{src:"cartesian-chart/05-share"}),t[8]||(t[8]=d("h3",{id:"时间轴",tabindex:"-1"},[c("时间轴 "),d("a",{class:"header-anchor",href:"#时间轴","aria-label":'Permalink to "时间轴"'},"​")],-1)),t[9]||(t[9]=d("p",null,"自变量给 Date，横轴换成时间比例尺：刻度按日期取整，间隔不均的日期按真实间距排开",-1)),o(e,{src:"cartesian-chart/06-time"}),t[10]||(t[10]=d("h3",{id:"语义系列",tabindex:"-1"},[c("语义系列 "),d("a",{class:"header-anchor",href:"#语义系列","aria-label":'Permalink to "语义系列"'},"​")],-1)),t[11]||(t[11]=d("p",null,"颜色本身带好坏含义时写 tone：收入取成功色、支出取危险色，不再按次序取分类色",-1)),o(e,{src:"cartesian-chart/07-tone"}),t[12]||(t[12]=d("h3",{id:"两张图联动",tabindex:"-1"},[c("两张图联动 "),d("a",{class:"header-anchor",href:"#两张图联动","aria-label":'Permalink to "两张图联动"'},"​")],-1)),t[13]||(t[13]=d("p",null,"两个量纲不共用一根 y 轴：两张图接到同一个受控的 activeKey，在同一个键上一起指示",-1)),o(e,{src:"cartesian-chart/08-linked"}),t[14]||(t[14]=d("h3",{id:"数据更新",tabindex:"-1"},[c("数据更新 "),d("a",{class:"header-anchor",href:"#数据更新","aria-label":'Permalink to "数据更新"'},"​")],-1)),t[15]||(t[15]=d("p",null,"换一组数据时柱从当前高度走到新高度，柱端的数随之滚动；关掉动画后直接画终态",-1)),o(e,{src:"cartesian-chart/09-transition"}),t[16]||(t[16]=d("h3",{id:"数据标签与合计",tabindex:"-1"},[c("数据标签与合计 "),d("a",{class:"header-anchor",href:"#数据标签与合计","aria-label":'Permalink to "数据标签与合计"'},"​")],-1)),t[17]||(t[17]=d("p",null,'labels="inside" 把每一段的数写在柱内，totals 在整叠外侧写合计；段太矮放不下时不写',-1)),o(e,{src:"cartesian-chart/10-labels"}),t[18]||(t[18]=d("h3",{id:"线尾标签",tabindex:"-1"},[c("线尾标签 "),d("a",{class:"header-anchor",href:"#线尾标签","aria-label":'Permalink to "线尾标签"'},"​")],-1)),t[19]||(t[19]=d("p",null,"endLabel 把系列名与末值写在线尾，末端挨着时上下推开、用引导线连回线尾；折线不多时读者不用对照图例",-1)),o(e,{src:"cartesian-chart/11-end-label"}),t[20]||(t[20]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>比较若干类目上的数值：各月销售额、各渠道转化量。</li><li>观察一个量随时间的变化趋势，或几个量的走势是否同步。</li><li>查看整体由哪几部分构成、各部分占比如何随类目变化（堆叠、百分比堆叠）。</li><li>类目名较长、或类目较多需要竖向滚读时，用横向的条形图。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>只报告一个数，或一个数与它的同比：使用<a href="./statistic">统计数值</a>。</li><li>少量类目在整体中的占比：使用饼图。</li><li>类目多于 7 个且每个都需要读出准确数字：使用<a href="./table">表格</a>，或表格与图并列。</li><li>两个量纲（如金额与转化率）：画两张图并用 <code>activeKey</code> 联动，不在一张图里放第二根 y 轴。两根 y 轴的刻度零点与比例都可以任意选，读者会把两条线的交叉读成含义，而它只是刻度选择的巧合。</li><li>看强度分布而不是具体数值：使用<a href="./heatmap">热力图</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>系列用 <code>mark</code> 区分画法，目前有 <code>bar</code> 与 <code>line</code> 两种。每个系列用字段名把数据的列映射到通道：<code>x</code> 是自变量，<code>y</code> 是数值。同一张图可以混放柱与折线，它们共用坐标轴。</li><li>数据是对象数组，组件只读不写。系列 <code>id</code> 缺省取 <code>y</code> 的字段名，<code>name</code> 缺省同 <code>id</code>；图例、提示框与数据表显示 <code>name</code>，<code>hiddenSeries</code> 与部件上的 <code>data-series-id</code> 使用 <code>id</code>。</li><li><code>x</code> 是自变量轴、<code>y</code> 是数值轴，与屏幕方向无关。<code>orientation=&quot;horizontal&quot;</code> 把整张图转置：自变量竖排、数值横向延伸，即条形图；<code>xAxis</code> / <code>yAxis</code> 的配置不用跟着对调。</li><li>比例尺缺省按数据推断：含柱系列或自变量不是数字与日期时为 <code>band</code>（类目），自变量是 <code>Date</code> 时为 <code>time</code>，是数字时为 <code>linear</code>；数值轴为 <code>linear</code>。<code>scale</code> 可显式指定 <code>band</code> / <code>point</code> / <code>linear</code> / <code>log</code> / <code>time</code> / <code>utc</code>。<code>log</code> 的定义域必须全为正数，否则报错并在根上写 <code>data-state=&quot;error&quot;</code>。</li><li>类目轴的顺序缺省是数据中首次出现的顺序，<code>xAxis.domain</code> 可给出显式顺序；只在 <code>domain</code> 里、数据中没有的类目也会占位。</li><li>有柱系列时数值轴强制包含 0：柱的长度就是它编码的量，基线不在 0 时长度之比不再等于数值之比。只有折线时 <code>zero</code> 缺省不强制，定义域贴合数据；需要从 0 起时写 <code>yAxis.zero</code>。</li><li>数值轴两端缺省取整到刻度上（<code>nice</code>），刻度数量按绘图区长度估算：竖向的数值轴约每 2.5 行字高一个，横向的按最宽的刻度标签加间隙估算；<code>ticks</code> 可以给数量提示或显式的刻度值。</li><li>同一 <code>stack</code> 名的系列堆叠在一起：柱逐段累加，折线成为堆叠面积。<code>stackOffset: &#39;expand&#39;</code> 把每个键归一成百分比，数值轴随之换成百分比格式；柱的堆叠含负值时缺省 <code>diverging</code>，正值向上、负值向下各自累加。同一堆叠组的 <code>stackOffset</code> 必须一致，不一致时报错。</li><li>多个柱系列不堆叠时并排分组：组内按系列次序排列，柱的厚度不超过 <code>--xh-chart-bar-max</code>（缺省 24px），类目很宽时柱不会被拉成大色块，多出的空间留作类目之间的间距。</li><li>堆叠的相邻两段之间留 <code>--xh-chart-gap</code>（2px）的表面缝，靠缝区分而不是靠描边。只有离基线最远的一端有圆角，基线一端始终是直角，读者据此判断柱是从哪里长出来的。</li><li>折线的 <code>curve</code> 缺省 <code>linear</code>；<code>monotone</code> 平滑且不越过数据点，不会画出数据中没有的峰谷；<code>step</code> / <code>step-before</code> / <code>step-after</code> 画成阶梯，台阶分别落在两点正中、前一点与后一点处，适合价格、库存这类在某一刻跳变的量。<code>area</code> 在折线下铺一层系列色的淡洗。缺失值（<code>null</code>、<code>undefined</code>、<code>NaN</code>）处折线断开，<code>connectNulls</code> 可改为连上。</li><li>折线的数据点 <code>symbols</code> 缺省 <code>auto</code>：相邻点间距不小于 16px 时才画，点密到连成一片时不画。键盘聚焦或悬停到折线上的数据时，那一个点总会画出来作为指示与焦点落点。</li><li>颜色按系列次序依次取分类色 1–8；<code>slot</code> 可把一个系列固定在某一色槽，同一业务实体在不同图表里保持同色。图例把某个系列隐藏后，其余系列的颜色不变。颜色本身带有好坏含义时（收入与支出、达标与超标）改写 <code>tone</code>，系列改用语气色；同一张图不混用分类色与语气色。</li><li>系列多于 8 个时报错：分类色只有 8 个可区分的色槽，第 9 个开始会与前面的系列撞色。需要更多系列时先合并或分成几张图。</li><li>数据标签由系列的 <code>labels</code> 打开：柱写 <code>inside</code>（柱内居中）或 <code>end</code>（柱的远端外侧，负值翻到另一侧；堆叠中的段写在段内的远端），折线写 <code>end</code>（每个点的上方）。柱内的字取与色槽配对的前景色；放不下、与更要紧的标签重叠时不写。柱端外侧的标签写在绘图区里：数值轴两端各收进一截，最高的那根柱上面也有地方写。</li><li><code>totals</code> 让每个堆叠组在整叠外侧写出合计，含负值时正负两端各写一个；百分比堆叠不写合计。</li><li>折线的 <code>endLabel</code> 在线尾写系列名与末值，几条线的末端挤在一起时上下推开，推开的标签用引导线连回线尾，挤不下去掉末值最小的；右边留出它要的地方。</li><li>标签按重要性落位：合计最先，其次线尾标签，最后逐个数据的标签；它们都只给眼睛看，数值由每个数据的可及名、摘要与数据表承担。</li><li>提示框缺省 <code>trigger=&quot;axis&quot;</code>：指针吸附到最近的键，列出该键上全部可见系列；<code>trigger=&quot;item&quot;</code> 只报告指针命中的那一个数据。键盘聚焦与指针悬停显示同样的内容。<code>tooltipOrder</code> 改变提示框里各系列的行序：缺省 <code>series</code> 按图例次序，<code>descending</code> / <code>ascending</code> 按数值排，缺失值排在最后；回调里的 <code>items</code> 仍按图例次序。</li><li>悬停图例项时，其余系列淡出到 <code>--xh-chart-dim-alpha</code>，该系列颜色不变；<code>trigger=&quot;item&quot;</code> 时悬停或聚焦某个数据同样只保留它所在的系列。<code>axis</code> 模式不淡出：提示框列出的正是该键上的全部系列。</li><li>提示框放在根内部，按指针所在的一侧翻转，不越出绘图区；它不进入浮层引擎，不参与浮层的层级与关闭协议。</li><li>坐标轴标签字体、柱的最大厚度、线宽、点的直径等几何量的真源是 CSS 组件槽：组件从根的计算样式读取它们再计算几何，改写组件槽就能改变几何，不需要布局属性。密度档切换时重新读取。</li><li>尺寸由视口决定：宽度随容器，高度取 <code>--xh-cartesian-chart-height</code>（缺省 <code>--xh-chart-height</code>）。视口尺寸变化时重新布局，服务端与首帧只输出空的绘图区、不占位跳动。</li><li><code>pending</code> 表示正在重新取数：保留上一帧、整体降低不透明度并在根上写 <code>aria-busy</code>，不闪骨架，也不跳布局。首次取数、手里还没有数据时，空态写 <code>translations.loadingText</code>（缺省 Loading…）并转一个圈，取完仍没有数据才写 <code>emptyText</code>。</li><li>首次出现时播放入场：柱沿数值轴从基线长出，折线从头描到尾，数据点等笔尖扫到才出现，面积、坐标轴与标签淡入，多个系列按图例次序错开（至多 5 步）。数据层的标记多于 1000 个时不做几何插值，只淡入淡出。之后的数据变化与图例切换从当前位置插值到新位置：留下的柱原地伸缩，新增的柱从基线长出，隐藏的系列收回基线并淡出后才移除；坐标轴刻度随之移动，数据标签、合计与线尾标签上的数从旧值滚到新值。标记按自变量的值对齐而不是按位置：类目换了次序时柱滑到新位置，时间序列往后推一格时整条线平移、新点从边上进来。<code>pending</code> 结束后到来的新数据按更新处理，不再重播入场。</li><li><code>animated={false}</code>（Web Components 写 <code>animated=&quot;false&quot;</code>）关闭过渡，数据一变直接画终态。系统开了减弱动效或容器写了 <code>data-motion=&quot;reduce&quot;</code> 时几何直接到位，只保留淡入淡出。视口尺寸变化与字体加载完成后的重排不播过渡。</li><li>过渡的快慢由动效令牌决定，组件从绘图区的计算样式读取：入场取 <code>--xh-motion-duration-reveal</code>（缺省 640ms），数据更新与图例切换取 <code>--xh-motion-duration-morph</code>（缺省 400ms）。在图或它的容器上改写它们，例如 <code>style=&quot;--xh-motion-duration-reveal: 1s&quot;</code>，只影响这张图；入场的曲线取 <code>--xh-motion-ease-enter-strong</code>，更新取 <code>--xh-motion-ease-continuous</code>。折线的描出与入场同一个时长。</li><li>没有数据或全部系列被隐藏时显示空态，文字取 <code>translations.emptyText</code>；坐标轴在全部隐藏时保留，图例仍可把系列点回来。</li><li>多张图接到同一个受控的 <code>activeKey</code> 上时，十字准线与提示框在同一个键上一起指示。从外部写入的键不触发 <code>onDatumActive</code>，只有本图上的指针与键盘才触发，联动不会来回回调。</li><li><code>onDatumPress</code> 只报告被点击或按下 Enter / Space 的数据，图表不内建选中态。</li><li>三个适配器的作者侧写法不同，最终 DOM 一致：Vue 与 React 不写默认内容时铺开缺省结构（标题、图例、视口与绘图区、空态、提示框），提示框内容可由作用域插槽 / 函数式 children 替换；Web Components 侧作者写外壳（root、caption、legend、viewport 与其中空的 <code>&lt;svg&gt;</code> plot、tooltip，可选 empty），网格、坐标轴、系列、图例项与提示框的缺省内容由元素生成进去，按标记的 key 复用节点。</li><li>Web Components 侧的数据、系列与坐标轴是对象，只走 JS property；朝向、提示框模式、<code>pending</code> 与 <code>locale</code> 另有同名属性，类目键的 <code>activeKey</code> 可写成 <code>active-key</code> 属性，数值与日期键走 property。宿主元素缺省是行内元素，放进 flex / grid 时要给它一个宽度，否则图按标题与图例的宽度收窄。</li><li>摘要与数据表由组件追加在根的末尾，三个适配器都一样，不需要作者放置。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>为图写标题：<code>caption</code> 是图的可访问名称，也是读者判断这张图在说什么的第一处。</li><li>折线不超过 4 条时，用 <code>endLabel</code> 把系列名写在线尾，读者不用在图例与线之间来回对照。</li><li>只在读者要读出准确数字时打开数据标签；每根柱都写数的图更像一张表，这时直接给表格。</li><li>类目名较长时改用横向条形图，而不是让横轴标签斜着排：竖排的类目名可以完整读出。</li><li>柱状图的类目顺序本身就是信息：没有自然顺序（如月份）的类目按数值排序后再给组件，组件不排序。</li><li>一张图的系列保持在 5 个以内，超过时读者需要反复对照图例。系列之间需要逐个比较时考虑分成几张小图。</li><li>折线图的自变量是时间时给 <code>Date</code>，不要先格式化成字符串：字符串会被当成类目，间隔不均匀的日期会被画成等距。</li><li>堆叠只在各部分之和有意义时使用：堆叠后只有最底下一段和总量能准确比较，中间各段的起点不齐，不适合逐段比较。</li><li>需要可见的表格视图时，把 <code>api.table</code> 交给<a href="./table">表格</a>组件，而不是在图下方另写一份数据。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用双 y 轴在一张图里放两个量纲：两根轴的刻度可以任意选，交叉点没有含义。</li><li>柱状图的数值轴不从 0 起：组件已强制包含 0，不要用 <code>min</code> 把它截掉。</li><li>用颜色区分同一个系列里的类目：颜色区分的是系列，类目已在坐标轴上。</li><li>用提示框作为读取数值的唯一途径：提示框对读屏隐藏，数值要能从坐标轴、摘要或数据表读到。</li><li>把几十个系列放进同一张图，再靠图例逐个点开：这时需要的是表格或筛选。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-cartesian-chart&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCartesianChartCaption</code> <code>XhCartesianChartEmpty</code> <code>XhCartesianChartLegend</code> <code>XhCartesianChartPlot</code> <code>XhCartesianChartRoot</code> <code>XhCartesianChartTooltip</code> <code>XhCartesianChartViewport</code></td></tr><tr><td>组合式函数</td><td><code>useCartesianChart</code></td></tr><tr><td>状态机</td><td><code>cartesianChartMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/cartesian-chart.css</code></td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hidden-series-change</code></td><td><code>ChartHiddenSeriesChangeDetails</code></td><td>图例切换显隐；detail 为 <code>{ hiddenSeries: string[] }</code></td></tr><tr><td><code>active-key-change</code></td><td><code>ChartActiveKeyChangeDetails</code></td><td>指针或键盘换了激活的键；detail 为 <code>{ activeKey }</code>，收起时为 null</td></tr><tr><td><code>datum-active</code></td><td><code>ChartDatumDetails</code></td><td>悬停或聚焦到某个数据；detail 为数据详情，收起时为 null</td></tr><tr><td><code>datum-press</code></td><td><code>ChartDatumDetails</code></td><td>指针点击、Enter 或 Space 按在某个数据上；detail 为数据详情</td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhCartesianChartRoot</code></td><td><code>default</code></td><td><code>CartesianChartRootSlotProps</code></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>caption</code></td><td>—</td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>tooltip</code></td><td><code>CartesianChartTooltipSlotProps</code></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>empty</code></td><td>—</td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhCartesianChartTooltip</code></td><td><code>default</code></td><td><code>CartesianChartTooltipSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to &quot;React 适配器 props&quot;">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhCartesianChartRoot</code></td><td><code>data</code></td><td><code>readonly ChartRow[]</code></td><td></td><td>数据：对象数组，系列用字段名把列映射到通道。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>series</code></td><td><code>readonly CartesianSeries[]</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>xAxis</code></td><td><code>CartesianAxis</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>yAxis</code></td><td><code>CartesianAxis</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>orientation</code></td><td><code>CartesianOrientation</code></td><td></td><td>朝向，缺省 vertical。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>trigger</code></td><td><code>CartesianTrigger</code></td><td></td><td>提示框汇报什么，缺省 axis。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>totals</code></td><td><code>boolean</code></td><td></td><td>堆叠柱的合计：每个堆叠组在最外端写出合计。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>tooltipOrder</code></td><td><code>CartesianTooltipOrder</code></td><td></td><td>提示框里各系列的行序，缺省 series（按图例次序）。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td><td>隐藏的系列（受控）。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>defaultHiddenSeries</code></td><td><code>string[]</code></td><td></td><td>初始隐藏的系列（非受控）。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td></td><td>激活的自变量键（受控）。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>pending</code></td><td><code>boolean</code></td><td></td><td>数据重取中：保留上一帧、整体降低不透明度。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>animated</code></td><td><code>boolean</code></td><td></td><td>播放过渡动画，缺省 true；false 时直接画终态。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>locale</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>translations</code></td><td><code>Partial&lt;CartesianChartTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>onHiddenSeriesChange</code></td><td><code>CartesianChartProps[&#39;onHiddenSeriesChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>onActiveKeyChange</code></td><td><code>CartesianChartProps[&#39;onActiveKeyChange&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>onDatumActive</code></td><td><code>CartesianChartProps[&#39;onDatumActive&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>onDatumPress</code></td><td><code>CartesianChartProps[&#39;onDatumPress&#39;]</code></td><td></td><td></td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>caption</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的标题内容。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>renderTooltip</code></td><td><code>(props: CartesianChartTooltipSlotProps) =&gt; ReactNode</code></td><td></td><td>缺省结构里的提示框内容。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>empty</code></td><td><code>ReactNode</code></td><td></td><td>缺省结构里的空态内容。</td></tr><tr><td><code>XhCartesianChartRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;CartesianChartRootSlotProps&gt;</code></td><td></td><td>自行摆放部件；不写时铺开缺省结构：图例、视口（绘图区与空态）、提示框。</td></tr><tr><td><code>XhCartesianChartTooltip</code></td><td><code>children</code></td><td><code>SlotChildren&lt;CartesianChartTooltipSlotProps&gt;</code></td><td></td><td>替换缺省内容；函数式 children 拿到激活的数据与缺省的内容模型。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>empty</code></td><td>&#39;loading&#39; | undefined</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>CartesianModel</code></td><td>管线产物：比例尺、布局、场景与无障碍模型。</td></tr><tr><td><code>scene</code></td><td><code>Scene</code></td><td>要画的场景；尚未测量时为空场景。</td></tr><tr><td><code>overlay</code></td><td><code>CartesianOverlay</code></td><td>前景层：随激活与聚焦变化的标记。绘图区按 back → under → data → over 的次序画： 十字准线与类目带淡底在数据之下，激活的点与焦点环在数据之上。</td></tr><tr><td><code>measured</code></td><td><code>boolean</code></td><td>视口尚未测量（服务端与首帧）：绘图区只输出空的 svg。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>没有可画的数据：空态部件据此显示。</td></tr><tr><td><code>legendItems</code></td><td><code>readonly CartesianLegendItem[]</code></td><td></td></tr><tr><td><code>active</code></td><td><code>ChartDatumDetails | null</code></td><td>激活的数据；没有时为 null。</td></tr><tr><td><code>tooltip</code></td><td><code>CartesianTooltipModel | null</code></td><td>提示框内容；收起时为 null。</td></tr><tr><td><code>summary</code></td><td><code>string</code></td><td>摘要文字。</td></tr><tr><td><code>table</code></td><td><code>TableModel</code></td><td>数据表模型：视觉隐藏的数据表用它，也可以喂给 Table 组件做可见的表格视图。</td></tr><tr><td><code>emptyText</code></td><td><code>string</code></td><td>空态文字。</td></tr><tr><td><code>tableCaption</code></td><td><code>string</code></td><td>数据表的标题。</td></tr><tr><td><code>activeKey</code></td><td><code>ChartKey | null</code></td><td>激活的自变量键。</td></tr><tr><td><code>hiddenSeries</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>toggleSeries</code></td><td><code>(id: string) =&gt; void</code></td><td>切换某个系列的显隐。</td></tr><tr><td><code>setFocusedDatum</code></td><td><code>(ref: { seriesId: string, index: number } | null) =&gt; void</code></td><td>移动键盘锚点。只改锚点不移动 DOM 焦点，也不派发回调； 需要焦点跟随时自行调用元素的 focus()。</td></tr><tr><td><code>markTag</code></td><td><code>(mark: Mark) =&gt; CartesianMarkTag</code></td><td>标记画成什么元素。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCaptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendItemProps</code></td><td><code>(item: CartesianLegendItem) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getLegendSwatchProps</code></td><td><code>(item: CartesianLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLegendLabelProps</code></td><td><code>(item: CartesianLegendItem) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPlotProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getMarkProps</code></td><td><code>(mark: Mark) =&gt; T[&#39;element&#39;]</code></td><td>场景里一个标记的属性（含 path 的 d、文字的坐标）。</td></tr><tr><td><code>getTooltipProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipRowProps</code></td><td><code>(row: CartesianTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipSwatchProps</code></td><td><code>(row: CartesianTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipValueProps</code></td><td><code>(row: CartesianTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTooltipNameProps</code></td><td><code>(row: CartesianTooltipRow) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getEmptyProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSummaryProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTableProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>总是</td><td>绘图区只占一个 Tab 位：焦点落到锚点数据，首次为第一个可见系列的第一个数据；图例同样只占一个 Tab 位</td></tr><tr><td><code>ArrowRight</code></td><td>焦点在绘图区</td><td>沿自变量方向移到下一个键（跳过缺失值）；horizontal 时由 ArrowDown 承担；已在末尾则原地不动</td></tr><tr><td><code>ArrowLeft</code></td><td>焦点在绘图区</td><td>沿自变量方向移到上一个键；horizontal 时由 ArrowUp 承担</td></tr><tr><td><code>ArrowUp</code></td><td>焦点在绘图区</td><td>在同一个键上换到视觉次序的下一个系列（堆叠自下而上、分组自左而右），跳过隐藏系列与缺失值；horizontal 时由 ArrowRight 承担</td></tr><tr><td><code>ArrowDown</code></td><td>焦点在绘图区</td><td>在同一个键上换到上一个系列；horizontal 时由 ArrowLeft 承担</td></tr><tr><td><code>Home</code></td><td>焦点在绘图区</td><td>当前系列的第一个数据</td></tr><tr><td><code>End</code></td><td>焦点在绘图区</td><td>当前系列的最后一个数据</td></tr><tr><td><code>PageUp</code> / <code>PageDown</code></td><td>焦点在绘图区</td><td>跨 10% 的键，至少 1 个</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在绘图区</td><td>报告聚焦的数据（onDatumPress）</td></tr><tr><td><code>Escape</code></td><td>提示框显示着</td><td>收起提示框，焦点留在原处；按键不拦截，外层浮层的关闭仍归它自己</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>Home</code> / <code>End</code></td><td>焦点在图例</td><td>在图例项之间移动，左右键跟随文字方向的视觉次序</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在图例项</td><td>切换该系列的显隐（原生按钮行为）</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>legend</code></td><td><code>aria-label</code></td><td>translations.legendLabel</td></tr><tr><td><code>legend</code></td><td><code>role</code></td><td>&#39;toolbar&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>aria-pressed</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>legend-swatch</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>plot</code></td><td><code>aria-describedby</code></td><td><code>summary</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-labelledby</code></td><td><code>caption</code> 部件的 id</td></tr><tr><td><code>plot</code></td><td><code>aria-roledescription</code></td><td>translations.chartRoleDescription</td></tr><tr><td><code>plot</code></td><td><code>role</code></td><td>&#39;graphics-document&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>mark</code></td><td><code>aria-hidden</code></td><td>mark.exiting || undefined</td></tr><tr><td><code>mark</code></td><td><code>aria-label</code></td><td>undefined | spec?.name</td></tr><tr><td><code>mark</code></td><td><code>aria-roledescription</code></td><td>undefined | translations.seriesRoleDescription</td></tr><tr><td><code>mark</code></td><td><code>role</code></td><td>undefined | &#39;graphics-object&#39;</td></tr></tbody></table><ul><li>根是 <code>&lt;figure&gt;</code>，可访问名称来自 <code>caption</code>（<code>&lt;figcaption&gt;</code>）；不放标题时在根上写 <code>aria-label</code>。只有两者都没有时开发期报 <code>chart.missing-name</code>。</li><li>绘图区是 <code>role=&quot;graphics-document&quot;</code>，<code>aria-roledescription</code> 取 <code>translations.chartRoleDescription</code>（缺省 chart），<code>aria-describedby</code> 指向组件生成的摘要。</li><li>每个系列是一个 <code>role=&quot;graphics-object&quot;</code> 的分组，名称是系列名；每根柱、每个焦点代理点是 <code>role=&quot;graphics-symbol&quot;</code>，名称取 <code>translations.datumLabel</code>（缺省“键, 系列名 值”），务必按本地语言改写。</li><li>坐标轴、网格、十字准线与焦点环一律 <code>aria-hidden</code>：它们的信息由每个数据的名称、摘要与数据表承担。</li><li>组件在根内生成一段摘要与一张数据表，二者视觉隐藏、对读屏可见，服务端即输出。摘要写系列数、自变量的范围以及每个系列的最小值与最大值，模板是 <code>translations.summary</code>；数据表首列是自变量，列名缺省取 x 轴标题，其余每个可见系列一列，缺失值写 <code>translations.missingValue</code>。</li><li>绘图区只占一个 Tab 位，进入后焦点落在一个真实的元素上：柱直接获得焦点；折线没有逐点的元素，由绘图区为聚焦的数据生成一个点作为焦点代理，移动时替换并聚焦新点，读屏据此播报新的名称。</li><li>焦点环是独立的 <code>focus-ring</code> 部件，画在标记之外，不依赖 SVG 元素的 outline；只在键盘聚焦时出现。</li><li>图例是 <code>role=&quot;toolbar&quot;</code>，名称取 <code>translations.legendLabel</code>；每一项是 <code>&lt;button aria-pressed&gt;</code>，按下表示系列可见。图例整体只占一个 Tab 位，进入后左右键在项之间移动。</li><li>提示框 <code>aria-hidden</code>：它显示的内容与数据的可访问名称是同一份，读两遍反而干扰。</li><li>Escape 收起提示框但不拦截按键，外层浮层的关闭仍由其自身处理。</li><li>过渡只改画面：数据的名称、摘要、数据表与焦点次序在数据变化的那一刻就按新数据更新；收场中的标记 <code>aria-hidden</code>、不可聚焦，也不响应指针。</li><li>颜色不是区分系列的唯一线索：图例文字、提示框中的系列名与数据名称都写出系列；折线与柱的色标形状也不同。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/cartesian-chart.css</code> 使用 <code>[data-scope=&quot;cartesian-chart&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>model.spec.orientation</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;error&#39; | undefined</td></tr><tr><td><code>root</code></td><td><code>data-xh-chart-part</code></td><td>&#39;root&#39;</td></tr><tr><td><code>caption</code></td><td><code>data-xh-chart-part</code></td><td>&#39;caption&#39;</td></tr><tr><td><code>legend</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>legend-item</code></td><td><code>data-tone</code></td><td>item.tone</td></tr><tr><td><code>legend-item</code></td><td><code>data-value</code></td><td>item.id</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-control</code></td><td>&#39;&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-profile</code></td><td>&#39;text&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-size</code></td><td>&#39;xs&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-action-variant</code></td><td>&#39;ghost&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-item&#39;</td></tr><tr><td><code>legend-item</code></td><td><code>data-xh-chart-slot</code></td><td>undefined | String(item.slot)</td></tr><tr><td><code>legend-swatch</code></td><td><code>data-mark</code></td><td>&#39;line&#39; | &#39;bar&#39;</td></tr><tr><td><code>legend-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;legend-swatch&#39;</td></tr><tr><td><code>viewport</code></td><td><code>data-xh-chart-part</code></td><td>&#39;viewport&#39;</td></tr><tr><td><code>plot</code></td><td><code>data-xh-chart-part</code></td><td>&#39;plot&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-placement</code></td><td>&#39;top&#39; | &#39;bottom&#39;-&#39;right&#39; | &#39;left&#39; | undefined</td></tr><tr><td><code>tooltip</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>tooltip</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip&#39;</td></tr><tr><td><code>tooltip-header</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-header&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-current</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-series-id</code></td><td>row.seriesId</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-tone</code></td><td>row.tone</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-row&#39;</td></tr><tr><td><code>tooltip-row</code></td><td><code>data-xh-chart-slot</code></td><td>undefined | String(row.slot)</td></tr><tr><td><code>tooltip-swatch</code></td><td><code>data-mark</code></td><td>&#39;line&#39; | &#39;bar&#39;</td></tr><tr><td><code>tooltip-swatch</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-swatch&#39;</td></tr><tr><td><code>tooltip-value</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-value&#39;</td></tr><tr><td><code>tooltip-name</code></td><td><code>data-xh-chart-part</code></td><td>&#39;tooltip-name&#39;</td></tr><tr><td><code>empty</code></td><td><code>data-state</code></td><td>&#39;loading&#39; | undefined</td></tr><tr><td><code>empty</code></td><td><code>data-xh-chart-part</code></td><td>&#39;empty&#39;</td></tr><tr><td><code>mark</code></td><td><code>data-axis</code></td><td>mark.key.slice(&#39;axis:&#39;.length) | undefined</td></tr><tr><td><code>mark</code></td><td><code>data-dimmed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>mark</code></td><td><code>data-drawing</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>mark</code></td><td><code>data-mark</code></td><td>spec?.mark</td></tr><tr><td><code>mark</code></td><td><code>data-placement</code></td><td>model.scene?.placements.get(mark.key) | undefined | undefined</td></tr><tr><td><code>mark</code></td><td><code>data-series-id</code></td><td>mark.key.slice(&#39;series:&#39;.length)</td></tr><tr><td><code>mark</code></td><td><code>data-tone</code></td><td>spec?.tone</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-part</code></td><td>mark.part | undefined</td></tr><tr><td><code>mark</code></td><td><code>data-xh-chart-slot</code></td><td>undefined | String(spec.slot)</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-cartesian-chart-bar-max</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-bar-max</code></td><td><code>default</code></td><td><code>--xh-chart-bar-max</code></td><td>cartesian-chart 的 root 部件 --xh-_chart-metric-bar-max 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-bar-radius</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>cartesian-chart 的 root 部件 --xh-_chart-metric-radius 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-empty-gap</code></td><td><code>empty</code></td><td><code>gap</code></td><td><code>state=loading</code></td><td><code>--xh-space-2</code></td><td>cartesian-chart 的 empty 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>cartesian-chart 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-height</code></td><td><code>viewport</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-chart-height</code></td><td>cartesian-chart 的 viewport 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-legend-gap</code></td><td><code>legend</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>cartesian-chart 的 legend 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-legend-swatch-line-radius</code></td><td><code>legend-swatch</code></td><td><code>border-radius</code></td><td><code>mark=line</code></td><td><code>--xh-shape-pill</code></td><td>cartesian-chart 的 legend-swatch 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-legend-swatch-radius</code></td><td><code>legend-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>cartesian-chart 的 legend-swatch 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-line-width</code></td><td><code>line</code><br><code>root</code></td><td><code>stroke-width</code></td><td><code>default</code></td><td><code>--xh-chart-line-width</code></td><td>cartesian-chart 的 line、root 部件 stroke-width 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-point-size</code></td><td><code>root</code></td><td><code>--xh-_chart-metric-point-size</code></td><td><code>default</code></td><td><code>--xh-chart-point-size</code></td><td>cartesian-chart 的 root 部件 --xh-_chart-metric-point-size 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-series-color</code></td><td><code>area-fill</code><br><code>bar</code><br><code>dot</code><br><code>legend-swatch</code><br><code>line</code><br><code>point</code><br><code>tooltip-swatch</code></td><td><code>background</code><br><code>border</code><br><code>fill</code><br><code>stroke</code></td><td><code>tone</code><br><code>xh-chart-slot=1</code><br><code>xh-chart-slot=2</code><br><code>xh-chart-slot=3</code><br><code>xh-chart-slot=4</code><br><code>xh-chart-slot=5</code><br><code>xh-chart-slot=6</code><br><code>xh-chart-slot=7</code><br><code>xh-chart-slot=8</code></td><td><code>--xh-_tone</code><br><code>--xh-chart-categorical-1</code><br><code>--xh-chart-categorical-2</code><br><code>--xh-chart-categorical-3</code><br><code>--xh-chart-categorical-4</code><br><code>--xh-chart-categorical-5</code><br><code>--xh-chart-categorical-6</code><br><code>--xh-chart-categorical-7</code><br><code>--xh-chart-categorical-8</code></td><td>cartesian-chart 的 area-fill、bar、dot、legend-swatch、line、point、tooltip-swatch 部件 background、border、fill、stroke 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-gap</code></td><td><code>tooltip</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>cartesian-chart 的 tooltip 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-px</code></td><td><code>tooltip</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>cartesian-chart 的 tooltip 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-py</code></td><td><code>tooltip</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-surface-pad-sm</code></td><td>cartesian-chart 的 tooltip 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-radius</code></td><td><code>tooltip</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-overlay</code></td><td>cartesian-chart 的 tooltip 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-row-gap</code></td><td><code>tooltip-row</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>cartesian-chart 的 tooltip-row 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-shadow</code></td><td><code>tooltip</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-shadow</code></td><td>cartesian-chart 的 tooltip 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-swatch-line-radius</code></td><td><code>tooltip-swatch</code></td><td><code>border-radius</code></td><td><code>mark=line</code></td><td><code>--xh-shape-pill</code></td><td>cartesian-chart 的 tooltip-swatch 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-cartesian-chart-tooltip-swatch-radius</code></td><td><code>tooltip-swatch</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>cartesian-chart 的 tooltip-swatch 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>动效角色：状态 · 出现 · 循环（见<a href="./../design/motion#角色">动效规范</a>）。</p><p>共享关键帧 <code>xh-draw</code> · <code>xh-fade-in</code> · <code>xh-spin</code> 由 <code>family/motion.css</code> 提供，皮肤 <code>@import</code> 它，单独引入仍成立；<code>opacity</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><ul><li>绘图区不随文字方向镜像：坐标系的方向是数据约定，时间在 rtl 页面上同样从左向右，左方向键始终向左。</li><li>图例、标题与提示框的内容随文字方向排列，图例的左右键跟随视觉次序翻转。</li><li>横向条形图的类目标签在 rtl 下同样位于左侧，数值轴同样从左向右增长。</li></ul>',56))])}const f=r(h,[["render",s]]);export{C as __pageData,f as default};
